#define LIGHT_SPELL_BASE_TICKS       10000
#define MAGIC_TORCH_BASE_TICKS       2000
#define FIRE_SHIELD_BASE_TICKS       100
#define MAGIC_MAP_TEXT               "MAGICMAP" /* the text of a magic map scroll */
/* Projectile spells: mana bonus min(8, maximum mana / 8); step energy 10 - bonus. A weak cast (kinetic energy
   below 4 * step energy) gets 3 more kinetic energy and step energy 9 - bonus. */
#define SPELL_MANA_BONUS_MAXIMUM     8
#define SPELL_MANA_BONUS_SHIFT       3
#define SPELL_STEP_ENERGY_BASE       10
#define SPELL_WEAK_KINETIC_FACTOR    4
#define SPELL_WEAK_KINETIC_BONUS     3
#define SPELL_WEAK_STEP_ENERGY_BASE  9
/* Kinetic energy of a projectile spell: (power + 2) * (2 * skill level + 4), from 21 to 255. */
#define SPELL_KINETIC_POWER_BONUS    2
#define SPELL_KINETIC_SKILL_BASE     4
#define SPELL_KINETIC_ENERGY_MINIMUM 21
#define SHIELD_DEFENSE_TICKS_SHIFT   5 /* a shield spell adds ticks / 32 defense */

/* Bit mask of the random term of a potion power. */
#define POTION_POWER_RANDOM_MASK    0xf
/* Other spells: the duration base is (power + 1) * 4. */
#define SPELL_DURATION_FACTOR       4
#define LIGHT_SPELL_TICKS_FACTOR    512 /* Light: (power - 1) * 4 * 512 + 10000 ticks */
#define MAGIC_TORCH_TICKS_FACTOR    128 /* Magic Torch: (power * 4 + 1) * 128 + 2000 ticks */
#define INVISIBILITY_TICKS_FACTOR   8
#define FOOTPRINTS_STRONG_POWER     3 /* from this power, footprints show all scents */
#define MAGIC_MAP_NETA_TICKS_FACTOR 4
#define MAGIC_MAP_ROS_DURATION_LOSS 2

static void add_party_event(uint8_t type, uint16_t ticks, uint16_t b)
{
    TimelineEvent event = {.map_time = EVENT_MAP_TIME(g_party_map_index, g_game_time + ticks), .type = type, .b = b};
    timeline_add_event(&event);
}

/* Sets redraw flags on all champions. */
static void set_attributes_of_all(uint16_t attributes)
{
    for (uint16_t i = 0; i < g_party_champion_count; i++)
        g_champions[i].attributes |= attributes;
}

void magic_create_light_event(int16_t light_power, uint16_t ticks)
{
    TimelineEvent event = {
        .map_time = EVENT_MAP_TIME(g_party_map_index, g_game_time + ticks), .type = EVENT_LIGHT, .b = light_power};
    timeline_add_event(&event);
    /* The view step recomputes the dungeon palette from the light amount. */
}

void magic_disable_action(int16_t champion_index, uint16_t ticks)
{
    Champion *c = &g_champions[champion_index];
    uint32_t time = g_game_time + ticks;
    if (c->enable_action_event_index < 0) {
        c->attributes |= CHAMPION_ATTR_ACTION_HAND | CHAMPION_ATTR_ACTION_DISABLED;
    } else {
        uint32_t old = g_timeline.events[c->enable_action_event_index].map_time & EVENT_TIME_MASK;
        if ((int32_t)time < (int32_t)old)
            time = old + (ticks >> 1);
        else
            time += (old - g_game_time) >> 1;
        timeline_delete_event(c->enable_action_event_index);
    }
    TimelineEvent event = {.map_time = EVENT_MAP_TIME(g_party_map_index, time),
                           .type = EVENT_ENABLE_CHAMPION_ACTION,
                           .priority = champion_index};
    c->enable_action_event_index = timeline_add_event(&event);
}

void magic_print_spell_failure(int16_t champion_index, int16_t failure_type, int16_t skill_index)
{
    int16_t first;
    if (failure_type == SPELL_FAILURE_NEEDS_MORE_PRACTICE) {
        if (skill_index >= SKILL_BASE_COUNT)
            skill_index = (skill_index - SKILL_BASE_COUNT) / SKILL_BASE_COUNT;
        first = skill_index == SKILL_WIZARD ? TEXT_SPELL_FAILURE_WIZARD : TEXT_SPELL_FAILURE_PRIEST;
    } else if (failure_type == SPELL_FAILURE_NEEDS_FLASK_IN_HAND) {
        first = TEXT_SPELL_FAILURE_FLASK;
    } else if (failure_type == SPELL_FAILURE_MEANINGLESS_SPELL) {
        first = TEXT_SPELL_FAILURE_MEANINGLESS;
    } else if (failure_type == SPELL_FAILURE_NEEDS_MAGIC_MAP) {
        first = TEXT_SPELL_FAILURE_MAGIC_MAP;
    } else {
        return;
    }
    message_new_line();
    message_print(MESSAGE_COLOR_CYAN, gfx_get_string(first));
    message_print(MESSAGE_COLOR_CYAN, g_champions[champion_index].name);
    message_print(MESSAGE_COLOR_CYAN, gfx_get_string(first + 1));
}

bool magic_is_projectile_spell_cast(int16_t champion_index, uint16_t thing, int16_t kinetic_energy,
                                    uint16_t required_mana)
{
    Champion *c = &g_champions[champion_index];
    if ((uint16_t)c->current_mana < required_mana) /* unsigned compare as in the original */
        return false;
    c->current_mana -= required_mana;
    c->attributes |= CHAMPION_ATTR_STATISTICS;
    int16_t mana_bonus = min16(SPELL_MANA_BONUS_MAXIMUM, c->maximum_mana >> SPELL_MANA_BONUS_SHIFT);
    int16_t step_energy = SPELL_STEP_ENERGY_BASE - mana_bonus;
    if (kinetic_energy < step_energy * SPELL_WEAK_KINETIC_FACTOR) {
        kinetic_energy += SPELL_WEAK_KINETIC_BONUS;
        step_energy = SPELL_WEAK_STEP_ENERGY_BASE - mana_bonus;
    }
    projectile_shoot_from_champion(champion_index, thing, (uint8_t)kinetic_energy, SPELL_PROJECTILE_ATTACK,
                                   (uint8_t)step_energy);
    return true;
}

bool magic_cast_party_spell(int16_t champion_index, bool spell_shield, uint16_t ticks, bool use_mana)
{
    Champion *c = &g_champions[champion_index];
    bool success = true;
    if (use_mana) {
        if (!c->current_mana)
            return false;
        if (c->current_mana < SHIELD_MANA_COST) {
            ticks >>= 1;
            c->current_mana = 0;
            success = false;
        } else {
            c->current_mana -= SHIELD_MANA_COST;
        }
    }
    int16_t defense = ticks >> SHIELD_DEFENSE_TICKS_SHIFT;
    int16_t *shield = spell_shield ? &g_party.spell_shield_defense : &g_party.fire_shield_defense;
    if (*shield > SHIELD_STRONG)
        defense >>= 2;
    *shield += defense;
    add_party_event(spell_shield ? EVENT_SPELL_SHIELD_END : EVENT_FIRE_SHIELD_END, ticks, defense);
    set_attributes_of_all(CHAMPION_ATTR_STATUS_BOX);
    return success;
}

/* The empty flask in the action hand, else in the ready hand, or THING_NONE. */
static uint16_t find_empty_flask(const Champion *c)
{
    for (int16_t slot = SLOT_HAND_ACTION; slot >= SLOT_HAND_READY; slot--)
        if (c->slots[slot] != THING_NONE && object_get_icon_index(c->slots[slot]) == ICON_EMPTY_FLASK)
            return c->slots[slot];
    return THING_NONE;
}

/* Fills an empty flask in a hand with the potion. Returns false without a flask. */
static bool cast_potion(int16_t champion_index, uint16_t potion_type, int16_t power)
{
    Champion *c = &g_champions[champion_index];
    uint16_t flask = find_empty_flask(c);
    if (flask == THING_NONE) {
        magic_print_spell_failure(champion_index, SPELL_FAILURE_NEEDS_FLASK_IN_HAND, 0);
        return false;
    }
    uint16_t empty_weight = inventory_get_object_weight(flask);
    rec_potion_set_type(flask, potion_type);
    rec_potion_set_power(flask, power * POTION_POWER_PER_LEVEL + (random16() & POTION_POWER_RANDOM_MASK));
    c->load += inventory_get_object_weight(flask) - empty_weight;
    if (champion_index == g_session.inventory_champion_index)
        c->attributes |= CHAMPION_ATTR_LOAD;
    return true;
}

/* The champion turns to the party direction and shoots the explosion of the spell. */
static void cast_projectile(int16_t champion_index, uint16_t explosion_type, int16_t power, uint16_t skill_level)
{
    Champion *c = &g_champions[champion_index];
    champion_face_party_direction(c);
    if (explosion_type == EXPLOSION_OPEN_DOOR)
        skill_level *= 2;
    int16_t kinetic_energy = bounded_value(
        SPELL_KINETIC_ENERGY_MINIMUM,
        (power + SPELL_KINETIC_POWER_BONUS) * (skill_level * 2 + SPELL_KINETIC_SKILL_BASE), KINETIC_ENERGY_MAXIMUM);
    magic_is_projectile_spell_cast(champion_index, EXPLOSION_THING(explosion_type), kinetic_energy, 0);
}

/* Light now, taken back by EVENT_LIGHT after the ticks. */
static void cast_light(uint16_t light_power, uint16_t ticks)
{
    g_party.magical_light_amount += tables_get_light_amount(light_power);
    magic_create_light_event(-light_power, ticks);
}

/* Zokathra: a new junk object in an empty hand, else on the party square. */
static void cast_zokathra(int16_t champion_index)
{
    uint16_t thing = discard_get_unused_thing(THING_JUNK);
    if (thing == THING_NONE)
        return;
    rec_junk_set_type(thing, JUNK_ZOKATHRA);
    const Champion *c = &g_champions[champion_index];
    int16_t slot = c->slots[SLOT_HAND_READY] == THING_NONE    ? SLOT_HAND_READY
                   : c->slots[SLOT_HAND_ACTION] == THING_NONE ? SLOT_HAND_ACTION
                                                              : -1;
    if (slot >= 0) {
        inventory_add_object_in_slot(champion_index, thing, slot);
    } else {
        move_get_move_result(&(Move){.thing = thing, .to.x = g_party_map_x, .to.y = g_party_map_y, .enters = true},
                             NULL);
    }
}

/* Spells of kind "other": light, darkness, thieves eye, invisibility, shields, magic torch, footprints, zokathra. */
static void cast_other(int16_t champion_index, uint16_t type, int16_t power)
{
    uint16_t ticks = (power + 1) * SPELL_DURATION_FACTOR;
    switch (type) {
    case SPELL_OTHER_LIGHT:
        cast_light((ticks >> 1) - 1,
                   (power - 1) * SPELL_DURATION_FACTOR * LIGHT_SPELL_TICKS_FACTOR + LIGHT_SPELL_BASE_TICKS);
        break;
    case SPELL_OTHER_DARKNESS:
        g_party.magical_light_amount -= tables_get_light_amount(ticks >> 2);
        magic_create_light_event(ticks >> 2, LIGHT_MAXIMUM_TICKS_DARKNESS);
        break;
    case SPELL_OTHER_THIEVES_EYE:
        g_party.thieves_eye_count++;
        ticks >>= 1;
        add_party_event(EVENT_THIEVES_EYE_END, ticks * ticks, 0);
        break;
    case SPELL_OTHER_INVISIBILITY:
        if (!g_party.invisibility_count++) {
            if (g_session.inventory_champion_index >= 0)
                g_champions[g_session.inventory_champion_index].attributes |= CHAMPION_ATTR_STATUS_BOX;
            set_attributes_of_all(CHAMPION_ATTR_ICON);
        }
        add_party_event(EVENT_INVISIBILITY_END, ticks * INVISIBILITY_TICKS_FACTOR, 0);
        break;
    case SPELL_OTHER_PARTY_SHIELD: {
        int16_t defense = ticks;
        if (g_party.shield_defense > SHIELD_STRONG)
            defense >>= 2;
        g_party.shield_defense += defense;
        set_attributes_of_all(CHAMPION_ATTR_STATUS_BOX);
        add_party_event(EVENT_PARTY_SHIELD_END, ticks * ticks, defense);
        break;
    }
    case SPELL_OTHER_MAGIC_TORCH:
        cast_light((ticks >> 2) + 1,
                   (power * SPELL_DURATION_FACTOR + 1) * MAGIC_TORCH_TICKS_FACTOR + MAGIC_TORCH_BASE_TICKS);
        break;
    case SPELL_OTHER_FOOTPRINTS:
        g_party.footprints_count++;
        g_party.first_scent_index = g_party.scent_count;
        g_party.last_scent_index = power < FOOTPRINTS_STRONG_POWER ? g_party.scent_count : 0;
        add_party_event(EVENT_FOOTPRINTS_END, ticks * ticks, 0);
        break;
    case SPELL_OTHER_ZOKATHRA:
        cast_zokathra(champion_index);
        break;
    case SPELL_OTHER_FIRE_SHIELD:
        magic_cast_party_spell(champion_index, false, ticks * ticks + FIRE_SHIELD_BASE_TICKS, false);
        break;
    }
}

bool magic_map_is_text(const char *text)
{
    return !strcmp(text, MAGIC_MAP_TEXT);
}

/* A magic map is a scroll with the text MAGICMAP. */
static bool is_magic_map(uint16_t thing)
{
    char text[SCROLL_TEXT_SIZE];
    if (THING_TYPE(thing) != THING_SCROLL)
        return false;
    dungeon_decode_text(text, sizeof text, THING_MAKE(THING_TEXT, rec_scroll_text_index(thing)),
                        TEXT_MODE_SCROLL | TEXT_MODE_ANY_VISIBILITY);
    return magic_map_is_text(text);
}

typedef struct {
    bool cast;
    uint16_t disabled_ticks;
} MagicMapCast;

/* CSB map spells need a magic map in the action hand. DAIN, ROS, and KU add a map layer for a time;
   NETA keeps the map of the party square and direction. cast is false without the map; disabled_ticks is set on the
   NETA path only. */
static MagicMapCast cast_magic_map(int16_t champion_index, uint16_t type, int16_t power)
{
    MagicMapCast result = {true, 0};
    Champion *c = &g_champions[champion_index];
    if (!is_magic_map(c->slots[SLOT_HAND_ACTION])) {
        magic_print_spell_failure(champion_index, SPELL_FAILURE_NEEDS_MAGIC_MAP, 0);
        return (MagicMapCast){false, 0};
    }
    uint16_t d = (power + 1) * SPELL_DURATION_FACTOR, ticks;
    if (type == MAGIC_MAP_NETA) {
        for (uint16_t i = 0; c->magic_map[MAGIC_MAP_NETA] && i < g_timeline.high_water; i++)
            if (g_timeline.events[i].type == EVENT_MAGIC_MAP_NETA_END &&
                g_timeline.events[i].priority == champion_index) {
                timeline_delete_event(i);
                break;
            }
        c->magic_map[MAGIC_MAP_NETA] = g_party_direction + 1;
        magic_set_map_position(c->magic_map, (Position){g_party_map_index, g_party_map_x, g_party_map_y});
        result.disabled_ticks = d * d >> 1;
        ticks = result.disabled_ticks * MAGIC_MAP_NETA_TICKS_FACTOR;
    } else {
        if (type == MAGIC_MAP_ROS)
            d -= MAGIC_MAP_ROS_DURATION_LOSS;
        else if (type == MAGIC_MAP_KU)
            d -= (d >> 2) - 1;
        c->magic_map[type]++;
        ticks = d * d * 2;
    }
    TimelineEvent event = {.map_time = EVENT_MAP_TIME(g_party_map_index, g_game_time + ticks),
                           .type = EVENT_MAGIC_MAP_DAIN_END + type,
                           .priority = champion_index};
    timeline_add_event(&event);
    return result;
}

/* The effect of the spell at the power; the skill level sets the energy of a projectile. Sets the ticks of the
   disabled action hand. Returns SPELL_CAST_FAILURE_NEEDS_FLASK without the flask or the magic map. */
static int16_t cast_effect(int16_t champion_index, const Spell *spell, int16_t power, uint16_t skill_level,
                           uint16_t *disabled_ticks)
{
    *disabled_ticks = spell->disabled_ticks;
    switch (spell->kind) {
    case SPELL_KIND_POTION:
        if (!cast_potion(champion_index, spell->type, power))
            return SPELL_CAST_FAILURE_NEEDS_FLASK;
        break;
    case SPELL_KIND_PROJECTILE:
        cast_projectile(champion_index, spell->type, power, skill_level);
        break;
    case SPELL_KIND_OTHER:
        cast_other(champion_index, spell->type, power);
        break;
    case SPELL_KIND_MAGIC_MAP: {
        MagicMapCast map_cast = cast_magic_map(champion_index, spell->type, power);
        if (!map_cast.cast)
            return SPELL_CAST_FAILURE_NEEDS_FLASK; /* the symbols stay, as without a flask */
        if (spell->type == MAGIC_MAP_NETA)
            *disabled_ticks = map_cast.disabled_ticks;
    } break;
    }
    return SPELL_CAST_SUCCESS;
}

int16_t magic_cast_champion_spell(int16_t champion_index)
{
    if (champion_index < 0 || champion_index >= g_party_champion_count)
        return SPELL_CAST_FAILURE;
    Champion *c = &g_champions[champion_index];
    if (!c->current_health)
        return SPELL_CAST_FAILURE;
    int16_t index = spell_find((const uint8_t *)c->symbols);
    if (index < 0) {
        magic_print_spell_failure(champion_index, SPELL_FAILURE_MEANINGLESS_SPELL, 0);
        return SPELL_CAST_FAILURE;
    }
    const Spell *spell = tables_get_spell(index);
    uint8_t power_symbol = c->symbols[0];
    int16_t power = (int8_t)power_symbol - (POWER_SYMBOL_FIRST - 1);
    uint16_t required_level = power + spell->base_required_skill_level;
    /* The original squares a stale register for the first term; the port uses required_level squared, as ReDMCSB intends. */
    uint16_t experience = required_level * required_level +
                          (power - 1) * spell->base_required_skill_level * SPELL_EXPERIENCE_POWER_FACTOR +
                          required_level * SPELL_EXPERIENCE_LEVEL_FACTOR + (random16() & SPELL_EXPERIENCE_RANDOM_MASK);
    uint16_t skill_level = champion_get_skill_level(champion_index, spell->skill_index, false, false);
    for (uint16_t missing = skill_level < required_level ? required_level - skill_level : 0; missing; missing--) {
        if (spell_draw_fails(c->statistics[STAT_WISDOM][STAT_CURRENT], random16())) {
            champion_add_skill_experience(champion_index, spell->skill_index,
                                          spell_get_failure_experience(experience, required_level, skill_level));
            magic_print_spell_failure(champion_index, SPELL_FAILURE_NEEDS_MORE_PRACTICE, spell->skill_index);
            return SPELL_CAST_FAILURE;
        }
    }
    uint16_t disabled_ticks;
    int16_t result = cast_effect(champion_index, spell, power, skill_level, &disabled_ticks);
    if (result != SPELL_CAST_SUCCESS)
        return result;
    champion_add_skill_experience(champion_index, spell->skill_index, experience);
    magic_disable_action(champion_index, disabled_ticks);
    return SPELL_CAST_SUCCESS;
}

int16_t magic_cast_cheat_spell(int16_t champion_index, int16_t spell_index)
{
    const Spell *spell = tables_get_spell(spell_index);
    if (!spell || champion_index < 0 || champion_index >= g_party_champion_count ||
        !g_champions[champion_index].current_health)
        return SPELL_CAST_FAILURE;
    uint8_t power_symbol = spell_get_packed_symbol(spell->symbols, 0);
    int16_t power = power_symbol ? power_symbol - (POWER_SYMBOL_FIRST - 1) : POWER_MON;
    uint16_t disabled_ticks;
    int16_t result =
        cast_effect(champion_index, spell, power,
                    champion_get_skill_level(champion_index, spell->skill_index, false, false), &disabled_ticks);
    if (result == SPELL_CAST_SUCCESS)
        magic_disable_action(champion_index, disabled_ticks);
    return result;
}

int16_t magic_click_cast_spell(void)
{
    int16_t result = magic_cast_champion_spell(g_magic_caster_champion_index);
    if (result == SPELL_CAST_FAILURE_NEEDS_FLASK)
        return SPELL_CAST_FAILURE;
    Champion *c = &g_champions[g_magic_caster_champion_index];
    c->symbols[0] = 0;
    c->symbol_step = 0;
    g_redraw |= REDRAW_SPELL_SYMBOLS;
    return result;
}

bool magic_add_champion_symbol(int16_t symbol)
{
    Champion *c = &g_champions[g_magic_caster_champion_index];
    uint16_t step = c->symbol_step;
    uint16_t cost = spell_get_symbol_mana_cost(step, symbol, (uint8_t)c->symbols[0]);
    if (cost > (uint16_t)c->current_mana)
        return false; /* unsigned compare as in the original */
    c->current_mana -= cost;
    c->attributes |= CHAMPION_ATTR_STATISTICS;
    c->symbols[step] = (char)spell_get_symbol(step, symbol);
    c->symbols[step + 1] = 0;
    c->symbol_step = NORMALIZE(step + 1);
    return true;
}

bool magic_delete_champion_symbol(void)
{
    Champion *c = &g_champions[g_magic_caster_champion_index];
    if (!c->symbols[0])
        return false;
    c->symbol_step = NORMALIZE(c->symbol_step - 1);
    c->symbols[c->symbol_step] = 0;
    return true;
}

bool magic_set_caster(int16_t champion_index)
{
    if (champion_index == g_magic_caster_champion_index ||
        (champion_index != -1 && !g_champions[champion_index].current_health))
        return false;
    g_magic_caster_champion_index = champion_index;
    return true;
}

