"""Save game sources: the original DOS PARTY.SAV directory and ScummVM slot files.

Both are decoded to the canonical 502-byte PARTY.SAV layout (see model.py)
and encoded back on save. Everything u4ed doesn't edit — monster tables,
ScummVM metadata and thumbnail, dungeon files — is carried over verbatim.

ScummVM slot layout (gzip-compressed, engines/ultima/ultima4/filesys/savegame.cpp):
    0x000-0x1D1  identical to PARTY.SAV
    u8 count, count x (x, y, z, map)          location chain, world first
    u16 orientation, u16 items, u8 stones, u8 runes
    11 x u16: members .. lastVirtue           same order as PARTY.SAV 0x1D8-0x1EC
    "MONS" + 256 bytes per map                current map, then previous
    "SVMCR" extended header (name, date, thumbnail); u32 offset of it at the very end
"""

from __future__ import annotations

import datetime as dt
import gzip
import re
import struct
from abc import ABC, abstractmethod
from dataclasses import dataclass
from pathlib import Path

from .model import (
    NOT_IN_DUNGEON, OFF_DNGLEVEL, OFF_DNGX, OFF_DNGY, OFF_LOCATION, OFF_ORIENT, PARTY_SAV_SIZE,
)

COMMON_PREFIX = 0x1D2
TAIL_OFFSET, TAIL_COUNT = 0x1D8, 11          # members .. lastVirtue
MONSTER_TABLE_SIZE = 256
MONS_TAG = b"MONS"
SVM_TAG = b"SVMCR\0"
SVM_VERSION = 4
CLASSIC_FILES = ("PARTY.SAV", "MONSTERS.SAV", "OUTMONST.SAV", "DNGMAP.SAV")
SLOT_RE = re.compile(r"^ultima4.*\.\d{3}$", re.IGNORECASE)


class FormatError(Exception):
    pass


# --- ScummVM -----------------------------------------------------------------

@dataclass
class ScummVMParts:
    prefix: bytes                                   # 0x000-0x1D1
    positions: list[tuple[int, int, int, int]]      # (x, y, z, map)
    orientation: int
    items: int
    stones: int
    runes: int
    tail: tuple[int, ...]                           # members .. lastVirtue
    rest: bytes                                     # MONS tables, extended header, trailer

    @property
    def monster_tables(self) -> list[bytes]:
        tables, pos = [], 0
        while self.rest[pos : pos + 4] == MONS_TAG:
            tables.append(self.rest[pos + 4 : pos + 4 + MONSTER_TABLE_SIZE])
            pos += 4 + MONSTER_TABLE_SIZE
        return tables

    @property
    def slot_name(self) -> str:
        if len(self.rest) < 4:
            return ""
        # the trailer stores the header's absolute offset; rest starts at party_len
        meta_off = struct.unpack_from("<I", self.rest, len(self.rest) - 4)[0] - self.party_len
        meta = self.rest[meta_off:] if 0 <= meta_off < len(self.rest) else b""
        if not meta.startswith(SVM_TAG) or len(meta) < 18:
            return ""
        return meta[18 : 18 + meta[17]].decode("latin1", "replace")

    @property
    def party_len(self) -> int:
        return COMMON_PREFIX + 1 + 4 * len(self.positions) + 6 + 2 * TAIL_COUNT

    def party_bytes(self) -> bytes:
        out = bytearray(self.prefix)
        out.append(len(self.positions))
        for pos in self.positions:
            out += bytes(pos)
        out += struct.pack("<2H2B", self.orientation, self.items, self.stones, self.runes)
        out += struct.pack(f"<{TAIL_COUNT}H", *self.tail)
        return bytes(out)


def scummvm_decompress(raw: bytes) -> bytes:
    return gzip.decompress(raw) if raw[:2] == b"\x1f\x8b" else raw


def parse_scummvm(raw: bytes) -> ScummVMParts:
    data = scummvm_decompress(raw)
    if len(data) < COMMON_PREFIX + 1:
        raise FormatError("too short for an Ultima IV ScummVM save")
    pos = COMMON_PREFIX
    count = data[pos]
    pos += 1
    positions = [tuple(data[pos + 4 * i : pos + 4 * i + 4]) for i in range(count)]
    pos += 4 * count
    if not positions or positions[0][3] != 0:
        raise FormatError(f"unexpected location chain {positions}")
    orientation, items, stones, runes = struct.unpack_from("<2H2B", data, pos)
    pos += 6
    tail = struct.unpack_from(f"<{TAIL_COUNT}H", data, pos)
    pos += 2 * TAIL_COUNT
    if data[pos : pos + 4] != MONS_TAG:
        raise FormatError("no MONS table where expected; not an Ultima IV save?")
    return ScummVMParts(data[:COMMON_PREFIX], positions, orientation, items, stones, runes,
                        tail, data[pos:])


def scummvm_to_canonical(parts: ScummVMParts) -> bytes:
    # PARTY.SAV: x/y = position on the current map, dngx/dngy = outer world position.
    # ScummVM: positions[0] = world, positions[-1] = (x, y, level, map) when inside.
    x, y, level, location = parts.positions[-1]
    if len(parts.positions) > 1:
        dx, dy = parts.positions[0][:2]
    else:
        dx, dy, level, location = 0, 0, NOT_IN_DUNGEON, 0
    out = bytearray(parts.prefix)
    out += struct.pack("<H4B", parts.items, x, y, parts.stones, parts.runes)
    out += struct.pack(f"<{TAIL_COUNT}H", *parts.tail)
    out += bytes([dx, dy])
    out += struct.pack("<3H", parts.orientation, level, location)
    assert len(out) == PARTY_SAV_SIZE
    return bytes(out)


def canonical_into_scummvm(canonical: bytes, parts: ScummVMParts) -> ScummVMParts:
    """New parts with the canonical party data; monsters and metadata kept."""
    c = canonical
    positions = list(parts.positions)
    if len(positions) > 1:
        level = struct.unpack_from("<H", c, OFF_DNGLEVEL)[0]
        location = struct.unpack_from("<H", c, OFF_LOCATION)[0]
        positions[0] = (c[OFF_DNGX], c[OFF_DNGY], positions[0][2], positions[0][3])
        positions[-1] = (c[0x1D4], c[0x1D5], level & 0xFF, location & 0xFF)
    else:
        positions[0] = (c[0x1D4], c[0x1D5], positions[0][2], positions[0][3])
    return ScummVMParts(
        prefix=c[:COMMON_PREFIX],
        positions=positions,
        orientation=struct.unpack_from("<H", c, OFF_ORIENT)[0],
        items=struct.unpack_from("<H", c, 0x1D2)[0],
        stones=c[0x1D6],
        runes=c[0x1D7],
        tail=struct.unpack_from(f"<{TAIL_COUNT}H", c, TAIL_OFFSET),
        rest=parts.rest,
    )


def encode_scummvm(parts: ScummVMParts) -> bytes:
    return gzip.compress(parts.party_bytes() + parts.rest, mtime=0)


def thumbnail(width: int = 160, height: int = 100) -> bytes:
    """A plain dark-blue RGB565 thumbnail in Graphics::saveThumbnail's layout."""
    pixel = struct.pack(">H", (0 << 11) | (8 << 5) | 12)
    header = struct.pack(">BHHB8B", 2, width, height, 2, 3, 2, 3, 8, 11, 5, 0, 0)
    body = header + pixel * (width * height)
    return b"THMB" + struct.pack(">I", 8 + len(body)) + body


def extended_header(description: str, offset: int, when: dt.datetime | None = None) -> bytes:
    """ScummVM's extended savegame header, appended after the game data."""
    when = when or dt.datetime.now()
    desc = description.encode("latin1", "replace")[:255]
    out = bytearray(SVM_TAG)
    out.append(SVM_VERSION)
    out += struct.pack("<I", (when.day << 24) | (when.month << 16) | when.year)
    out += struct.pack("<H", (when.hour << 8) | when.minute)
    out += struct.pack("<I", 0)                      # play time
    out.append(len(desc))
    out += desc
    out.append(0)                                    # not an autosave
    out += thumbnail()
    out += struct.pack("<I", offset)
    return bytes(out)


def canonical_to_new_scummvm(canonical: bytes, monsters: bytes | None, description: str) -> bytes:
    """Build a fresh ScummVM slot from a surface PARTY.SAV (+ MONSTERS.SAV)."""
    location = struct.unpack_from("<H", canonical, OFF_LOCATION)[0]
    if location != 0:
        raise FormatError("the classic save is inside a town or dungeon; only surface saves "
                          "can be exported to ScummVM")
    skeleton = ScummVMParts(canonical[:COMMON_PREFIX], [(0, 0, 0, 0)], 0, 0, 0, 0,
                            (0,) * TAIL_COUNT, b"")
    parts = canonical_into_scummvm(canonical, skeleton)
    monsters = (monsters or bytes(MONSTER_TABLE_SIZE))[:MONSTER_TABLE_SIZE]
    body = parts.party_bytes() + MONS_TAG + monsters.ljust(MONSTER_TABLE_SIZE, b"\0")
    return gzip.compress(body + extended_header(description, len(body)), mtime=0)


# --- sources -----------------------------------------------------------------------

class Source(ABC):
    """Where a save lives. ``files`` are the raw on-disk files (for history)."""

    kind: str
    path: Path

    @abstractmethod
    def read_files(self) -> dict[str, bytes]: ...

    @abstractmethod
    def decode(self, files: dict[str, bytes]) -> bytes:
        """Raw files -> canonical PARTY.SAV bytes."""

    @abstractmethod
    def encode(self, canonical: bytes, files: dict[str, bytes]) -> dict[str, bytes]:
        """Canonical bytes applied onto ``files`` -> raw files to write."""

    @abstractmethod
    def write_files(self, files: dict[str, bytes]) -> None: ...

    @property
    @abstractmethod
    def history_dir(self) -> Path: ...

    @property
    @abstractmethod
    def label(self) -> str: ...


class ClassicSource(Source):
    kind = "classic"

    def __init__(self, directory: Path):
        self.path = Path(directory)
        self.names = {}
        for p in self.path.iterdir():
            for name in CLASSIC_FILES:
                if p.name.upper() == name:
                    self.names[name] = p.name
        if "PARTY.SAV" not in self.names:
            raise FormatError(f"no PARTY.SAV in {self.path}")

    def read_files(self) -> dict[str, bytes]:
        return {name: (self.path / real).read_bytes() for name, real in self.names.items()}

    def decode(self, files: dict[str, bytes]) -> bytes:
        party = files["PARTY.SAV"]
        if len(party) != PARTY_SAV_SIZE:
            raise FormatError(f"PARTY.SAV has {len(party)} bytes, expected {PARTY_SAV_SIZE}")
        return party

    def encode(self, canonical: bytes, files: dict[str, bytes]) -> dict[str, bytes]:
        return {**files, "PARTY.SAV": bytes(canonical)}

    def write_files(self, files: dict[str, bytes]) -> None:
        for name, data in files.items():
            real = self.names.get(name, name)
            (self.path / real).write_bytes(data)
            self.names[name] = real

    @property
    def history_dir(self) -> Path:
        return self.path / ".u4ed-history"

    @property
    def label(self) -> str:
        return f"classic: {self.path}"


class ScummVMSource(Source):
    kind = "scummvm"

    def __init__(self, file: Path):
        self.path = Path(file)
        self.parts = parse_scummvm(self.path.read_bytes())

    def read_files(self) -> dict[str, bytes]:
        return {self.path.name: self.path.read_bytes()}

    def decode(self, files: dict[str, bytes]) -> bytes:
        self.parts = parse_scummvm(files[self.path.name])
        return scummvm_to_canonical(self.parts)

    def encode(self, canonical: bytes, files: dict[str, bytes]) -> dict[str, bytes]:
        raw = files[self.path.name]
        new = canonical_into_scummvm(canonical, parse_scummvm(raw))
        if new.party_bytes() + new.rest == scummvm_decompress(raw):
            return {self.path.name: raw}         # unchanged: don't recompress
        return {self.path.name: encode_scummvm(new)}

    def write_files(self, files: dict[str, bytes]) -> None:
        if self.path.name in files:
            self.path.write_bytes(files[self.path.name])

    @property
    def history_dir(self) -> Path:
        return self.path.parent / ".u4ed-history" / self.path.name

    @property
    def label(self) -> str:
        name = self.parts.slot_name
        return f"ScummVM: {self.path}" + (f" ({name!r})" if name else "")


def list_slots(directory: Path) -> list[tuple[Path, str]]:
    out = []
    for p in sorted(Path(directory).iterdir()):
        if p.is_file() and SLOT_RE.match(p.name):
            try:
                out.append((p, parse_scummvm(p.read_bytes()).slot_name))
            except (FormatError, OSError, EOFError, struct.error, gzip.BadGzipFile):
                continue
    return out


def detect(path: Path) -> Source:
    """Autodetect: a ScummVM slot file, a PARTY.SAV file, or a directory with PARTY.SAV."""
    path = Path(path).expanduser()
    if path.is_file():
        if path.name.upper() == "PARTY.SAV":
            return ClassicSource(path.parent)
        try:
            return ScummVMSource(path)
        except (FormatError, EOFError, struct.error, gzip.BadGzipFile, OSError) as exc:
            raise FormatError(f"{path} is neither PARTY.SAV nor a ScummVM Ultima IV save ({exc})")
    if path.is_dir():
        try:
            return ClassicSource(path)
        except FormatError:
            slots = list_slots(path)
            if slots:
                listing = "\n".join(f"  {p}  {n!r}" for p, n in slots)
                raise FormatError(f"{path} holds ScummVM slots; pick one:\n{listing}") from None
            raise
    raise FormatError(f"{path} not found")


# --- export -------------------------------------------------------------------------

def export(source: Source, canonical: bytes, files: dict[str, bytes], target: Path,
           description: str = "") -> list[Path]:
    """Write the save in the *other* format. Returns the written paths.

    classic -> ScummVM: ``target`` is the slot file to create (e.g. ultima4_enh.005).
    ScummVM -> classic: ``target`` is a directory; PARTY.SAV and MONSTERS.SAV are written.
    """
    target = Path(target).expanduser()
    location = struct.unpack_from("<H", canonical, OFF_LOCATION)[0]
    if source.kind == "classic":
        if target.is_dir():
            raise FormatError(f"{target} is a directory; give the slot file, e.g. ultima4_enh.005")
        data = canonical_to_new_scummvm(canonical, files.get("MONSTERS.SAV"),
                                        description or "Imported by u4ed")
        target.write_bytes(data)
        return [target]
    if location != 0:
        raise FormatError("this ScummVM save is inside a town or dungeon; the original game "
                          "keeps that state in extra files ScummVM doesn't store. Save on the "
                          "surface and export that one.")
    parts = parse_scummvm(files[source.path.name])
    target.mkdir(parents=True, exist_ok=True)
    written = []
    tables = parts.monster_tables
    for name, data in (("PARTY.SAV", bytes(canonical)),
                       ("MONSTERS.SAV", tables[0] if tables else bytes(MONSTER_TABLE_SIZE))):
        path = target / name
        path.write_bytes(data)
        written.append(path)
    return written

