namespace ScummExplorer.Core.V5;

/// <summary>
/// Parses the SCUMM v5 "new directory" block stream: [4-char ASCII tag]
/// [4-byte big-endian size incl. header][payload], recursively for
/// container tags. Ported from ScummVM's generic resource iterator
/// (engines/scumm/resource.cpp - loadResource/findResource, which treat
/// every block uniformly as tag+BE-size regardless of nesting depth).
/// </summary>
public static class BlockParserV5
{
    private const int HeaderSize = 8;

    // LFLF/ROOM/RMIM/OBIM/OBCD always recurse. Per-image-state blocks
    // ("IM00".."IM99", both room and per-object) also recurse (they hold
    // "SMAP" + "ZPxx" children) - matched structurally below rather than by
    // name, since there can be dozens of them. "LOFF" and "IMHD"/"CDHD"
    // start with similar-looking prefixes but are plain leaf/data blocks.
    private static readonly HashSet<string> ContainerTags = ["LECF", "LFLF", "ROOM", "RMIM", "OBIM", "OBCD"];

    public static List<ScummBlockV5> ParseRange(byte[] data, long start, long end, ScummBlockV5? parent)
    {
        var result = new List<ScummBlockV5>();
        long offset = start;

        while (offset + HeaderSize <= end)
        {
            string tag = ReadTag(data, offset);
            uint size = ReadUInt32BE(data, offset + 4);

            // A zero/garbage size means we've hit padding or trailing data; stop here
            // rather than looping forever or reading past the buffer.
            if (size < HeaderSize || offset + size > end)
                break;

            var block = new ScummBlockV5
            {
                Tag = tag,
                Offset = offset,
                Size = size,
                HeaderSize = HeaderSize,
                Parent = parent,
            };

            if (tag == "SOUN")
            {
                block.Children.AddRange(ParseSounChildren(data, offset + HeaderSize, offset + size, block));
            }
            else if (IsContainer(data, offset, size, tag))
            {
                var children = ParseRange(data, offset + HeaderSize, offset + size, block);
                block.Children.AddRange(children);
            }

            result.Add(block);
            offset += size;
        }

        return result;
    }

    /// <summary>
    /// Parses a "SOUN" resource's payload (ScummVM's readSoundResource,
    /// resource.cpp): a single nested block whose own tag ("basetag")
    /// determines the shape. If basetag is "SOU " (with a trailing space),
    /// it's itself a container of one entry per supported sound driver -
    /// "ADL " (AdLib), "ROL " (Roland MT-32), "SPK " (PC Speaker/PCjr),
    /// "SBL " (Sound Blaster), "GMD " (General MIDI), "AMI "/"MAC "/"TOWS"
    /// (Amiga/Macintosh/FM-Towns) - and the real engine picks whichever one
    /// matches the configured music driver at runtime; every entry is kept
    /// here for browsing. Any other basetag ("MIDI"/"iMUS" - a raw/digital
    /// music track with no per-driver alternatives) is a single opaque leaf.
    ///
    /// Every size field *inside* "SOUN" (both "SOU "'s own and each of its
    /// children's) uses a different convention from every other v5+ tag in
    /// this codebase: the declared value is *payload-only*, excluding the
    /// tag's own 8-byte header, unlike the "size includes header" convention
    /// <see cref="ParseRange"/> uses uniformly elsewhere (confirmed directly
    /// against ScummVM's own source: "size = fetchUint32BE() + 8;" for each
    /// child, vs. the outer "SOUN" tag's own "max_total_size = ...() - 8;").
    /// Confirmed empirically against every real "SOUN" block in both
    /// MONKEY2.001 and ATLANTIS.001: 410/412 parse cleanly to their exact
    /// declared end with this "+8" convention (0/412 with the naive
    /// "size includes header" one). The 2 exceptions are a real, benign data
    /// quirk - genuine MONKEY2 "SOU " containers whose own declared size is
    /// 0 despite having a real trailing "ADL " child - confirmed this isn't
    /// a bug in this reader by tracing ScummVM's own loop
    /// ("while (pos &lt; total_size)"): with total_size == 0 the real engine's
    /// loop body never runs either, so it never finds *any* sound data for
    /// that resource - a pre-existing, silent playback gap in the original
    /// game, not something to special-case around. The leftover, unreachable
    /// bytes are surfaced as a visible "??" leaf rather than silently
    /// dropped, matching the same convention already used for "SO" in
    /// V3V4/BlockParser.
    /// </summary>
    private static List<ScummBlockV5> ParseSounChildren(byte[] data, long start, long end, ScummBlockV5 sounParent)
    {
        var result = new List<ScummBlockV5>();
        if (start + HeaderSize > end)
            return result;

        // Full Throttle: no basetag/wrapper at all - "SOUN"'s payload directly IS
        // a Creative Voice File, the same VOC format MONSTER.SOU's clips use (see
        // MonsterSou.VocDecoder, reused unmodified here). Confirmed empirically:
        // 695/695 real "SOUN" blocks in FT.LA1 start with the VOC magic directly,
        // no "SOU "/"iMUS"/other wrapper tag at all.
        if (IsVocHeader(data, start))
        {
            result.Add(new ScummBlockV5 { Tag = "VOC ", Offset = start, Size = (uint)(end - start), HeaderSize = 0, Parent = sounParent });
            return result;
        }

        string baseTag = ReadTag(data, start);

        // "iMUS" is the one basetag that does NOT use "SOU "'s payload-only size
        // convention - its own size field already includes its 8-byte header,
        // same as every other v5+ tag - so it needs its own validation, checked
        // before the "+8" logic below (which would otherwise reject it: its
        // declared size already fills the rest of "SOUN"'s payload exactly, so
        // adding another 8 pushes it 8 bytes past the end).
        if (baseTag == "iMUS")
            return ParseImusChildren(data, start, end, sounParent, result);

        uint baseRawSize = ReadUInt32BE(data, start + 4);
        long baseTotal = baseRawSize + HeaderSize;
        if (baseTotal < HeaderSize || start + baseTotal > end)
            return result;

        if (baseTag != "SOU ")
        {
            // A single opaque leaf (e.g. "MIDI") - no per-driver alternatives to browse.
            result.Add(new ScummBlockV5 { Tag = baseTag, Offset = start, Size = (uint)baseTotal, HeaderSize = HeaderSize, Parent = sounParent });
            return AddTrailingUnparsed(data, start + baseTotal, end, sounParent, result);
        }

        var souBlock = new ScummBlockV5 { Tag = baseTag, Offset = start, Size = (uint)baseTotal, HeaderSize = HeaderSize, Parent = sounParent };
        result.Add(souBlock);

        long childPos = start + HeaderSize;
        long budget = baseRawSize; // "SOU "'s own declared size, payload-only convention
        long consumed = 0;
        while (consumed < budget && childPos + HeaderSize <= end)
        {
            string childTag = ReadTag(data, childPos);
            uint childRawSize = ReadUInt32BE(data, childPos + 4);
            long childTotal = childRawSize + HeaderSize;
            if (childTotal < HeaderSize || childPos + childTotal > end)
                break;

            souBlock.Children.Add(new ScummBlockV5 { Tag = childTag, Offset = childPos, Size = (uint)childTotal, HeaderSize = HeaderSize, Parent = souBlock });
            childPos += childTotal;
            consumed += childTotal;
        }

        return AddTrailingUnparsed(data, Math.Max(childPos, start + baseTotal), end, sounParent, result);
    }

    /// <summary>
    /// Parses "SOUN" &gt; "iMUS" - The Dig's (and, per ScummVM source, COMI's)
    /// digital-audio SOUN variant, structurally unrelated to "SOU "'s per-driver
    /// MIDI wrapper above. "iMUS" wraps a single "MAP " block (metadata: a
    /// "FRMT" giving sample format, plus "REGN"/"TEXT"/"JUMP"/"SYNC"/"STOP"
    /// entries used for runtime looping/lip-sync, all using the same
    /// payload-only convention as "SOU "'s own children) immediately followed
    /// by one "DATA" block holding the raw PCM sample bytes - see
    /// <see cref="ImuseDigiSoundReader"/> for the decode. Confirmed empirically
    /// against every real "SOUN" in The Dig's DIG.LA1 (359/359 parse cleanly);
    /// a handful (31/359) have 1-3 stray trailing bytes after "DATA"'s own
    /// declared content before "iMUS"'s own end - the same kind of benign
    /// padding quirk seen elsewhere in this codebase (e.g.
    /// <see cref="MonsterSou.MonsterSouFile"/>'s Full Throttle clips) - surfaced
    /// via the same "??" trailing-unparsed convention "SOU " already uses,
    /// rather than silently folded into "DATA" or dropped. One real clip
    /// (1/359) also has "iMUS"'s own declared size undercount the real "DATA"
    /// span by exactly 8 bytes - "DATA" is therefore located using "SOUN"'s
    /// own outer budget (<paramref name="end"/>) as the bound, not "iMUS"'s own
    /// declared size, the same "trust the outer container's budget over a
    /// nested tag's own declared size" approach "SOU "'s own children loop
    /// above already uses - and "iMUS"'s reported <see cref="ScummBlockV5.Size"/>
    /// is widened to cover "DATA" in full when this happens, rather than
    /// reporting a size smaller than its own children's actual span.
    /// </summary>
    private static List<ScummBlockV5> ParseImusChildren(byte[] data, long start, long end, ScummBlockV5 sounParent, List<ScummBlockV5> result)
    {
        // Unlike "SOU "'s children, "iMUS"'s own size field already includes
        // its 8-byte header (the normal v5+ convention).
        uint imusDeclaredSize = ReadUInt32BE(data, start + 4);
        if (imusDeclaredSize < HeaderSize || start + imusDeclaredSize > end)
            return result;

        long declaredEnd = start + imusDeclaredSize;
        long mapStart = start + HeaderSize;
        if (mapStart + HeaderSize > end || ReadTag(data, mapStart) != "MAP ")
            return AddTrailingUnparsed(data, declaredEnd, end, sounParent, AddImusLeaf(imusDeclaredSize, [], start, sounParent, result));

        // "MAP " and its children use the same payload-only convention as "SOU "'s.
        uint mapPayloadSize = ReadUInt32BE(data, mapStart + 4);
        long mapTotal = mapPayloadSize + HeaderSize;
        if (mapTotal < HeaderSize || mapStart + mapTotal > end)
            return AddTrailingUnparsed(data, declaredEnd, end, sounParent, AddImusLeaf(imusDeclaredSize, [], start, sounParent, result));

        var mapBlock = new ScummBlockV5 { Tag = "MAP ", Offset = mapStart, Size = (uint)mapTotal, HeaderSize = HeaderSize };
        var imusChildren = new List<ScummBlockV5> { mapBlock };

        long childPos = mapStart + HeaderSize;
        long mapChildrenEnd = mapStart + mapTotal;
        while (childPos + HeaderSize <= mapChildrenEnd)
        {
            string childTag = ReadTag(data, childPos);
            uint childPayloadSize = ReadUInt32BE(data, childPos + 4);
            long childTotal = childPayloadSize + HeaderSize;
            if (childTotal < HeaderSize || childPos + childTotal > mapChildrenEnd)
                break;

            mapBlock.Children.Add(new ScummBlockV5 { Tag = childTag, Offset = childPos, Size = (uint)childTotal, HeaderSize = HeaderSize, Parent = mapBlock });
            childPos += childTotal;
        }

        // "DATA" immediately follows "MAP ", same payload-only convention.
        long afterData = mapChildrenEnd;
        if (afterData + HeaderSize <= end && ReadTag(data, afterData) == "DATA")
        {
            uint dataPayloadSize = ReadUInt32BE(data, afterData + 4);
            long dataTotal = dataPayloadSize + HeaderSize;
            if (dataTotal >= HeaderSize && afterData + dataTotal <= end)
            {
                imusChildren.Add(new ScummBlockV5 { Tag = "DATA", Offset = afterData, Size = (uint)dataTotal, HeaderSize = HeaderSize });
                afterData += dataTotal;
            }
        }

        // "iMUS"'s real span is whichever is bigger: its own declared size, or
        // how far its children actually reached (see the 8-byte-undercount
        // quirk mentioned above).
        long realEnd = Math.Max(declaredEnd, afterData);
        if (afterData < realEnd)
            imusChildren.Add(new ScummBlockV5 { Tag = "??", Offset = afterData, Size = (uint)(realEnd - afterData), HeaderSize = 0 });

        var addResult = AddImusLeaf((uint)(realEnd - start), imusChildren, start, sounParent, result);
        return AddTrailingUnparsed(data, realEnd, end, sounParent, addResult);
    }

    /// <summary>Builds the "iMUS" node itself once its real total size is known, attaching the already-built children (whose own <c>Parent</c> still needs wiring up, since <see cref="ScummBlockV5.Size"/> is immutable and the parent can't be constructed until its children's total span is known).</summary>
    private static List<ScummBlockV5> AddImusLeaf(uint size, List<ScummBlockV5> children, long start, ScummBlockV5 sounParent, List<ScummBlockV5> result)
    {
        var imusBlock = new ScummBlockV5 { Tag = "iMUS", Offset = start, Size = size, HeaderSize = HeaderSize, Parent = sounParent };
        foreach (var child in children)
        {
            child.Parent = imusBlock;
            imusBlock.Children.Add(child);
        }
        result.Add(imusBlock);
        return result;
    }

    /// <summary>Surfaces any bytes between a "SOUN" resource's parsed content and its own declared end as a visible "??" leaf, rather than silently dropping them - see <see cref="ParseSounChildren"/>'s doc comment for the real (benign) data quirk this catches.</summary>
    private static List<ScummBlockV5> AddTrailingUnparsed(byte[] data, long from, long end, ScummBlockV5 sounParent, List<ScummBlockV5> result)
    {
        if (from < end)
            result.Add(new ScummBlockV5 { Tag = "??", Offset = from, Size = (uint)(end - from), HeaderSize = 0, Parent = sounParent });
        return result;
    }

    /// <summary>
    /// "SMAP" is a container only for v8 (Curse of Monkey Island), which wraps
    /// its strip data in a nested "BSTR" sub-block (see <see cref="V5.StripImageDecoderV5"/>
    /// and <see cref="V8.ZPlaneReaderV8"/>) - v5/v6/v7's "SMAP" is a flat leaf
    /// (strip table + raw, untagged strip bytes directly in its own payload),
    /// so recursing into it unconditionally would misinterpret that raw data as
    /// bogus tag+size pairs. Unlike every other container tag, this can't be
    /// decided from the tag name alone, so it's the one case that peeks at the
    /// payload's own leading bytes.
    /// </summary>
    private static bool IsContainer(byte[] data, long offset, uint size, string tag)
    {
        if (tag == "SMAP")
            return offset + HeaderSize + 4 <= offset + size
                && offset + HeaderSize + 4 <= data.Length
                && data[offset + HeaderSize] == 'B' && data[offset + HeaderSize + 1] == 'S'
                && data[offset + HeaderSize + 2] == 'T' && data[offset + HeaderSize + 3] == 'R';

        return ContainerTags.Contains(tag) ||
            (tag.Length == 4 && tag[0] == 'I' && tag[1] == 'M' && Uri.IsHexDigit(tag[2]) && Uri.IsHexDigit(tag[3])) ||
            V6.TagCatalogV6.ContainerTags.Contains(tag) ||
            V7.TagCatalogV7.ContainerTags.Contains(tag) ||
            V8.TagCatalogV8.ContainerTags.Contains(tag);
    }

    private static bool IsVocHeader(byte[] data, long offset)
    {
        ReadOnlySpan<byte> magic = "Creative Voice File"u8;
        if (offset + magic.Length + 1 > data.Length)
            return false;
        for (int i = 0; i < magic.Length; i++)
            if (data[offset + i] != magic[i])
                return false;
        return data[offset + magic.Length] == 0x1A;
    }

    private static uint ReadUInt32BE(byte[] data, long offset) =>
        (uint)((data[offset] << 24) | (data[offset + 1] << 16) | (data[offset + 2] << 8) | data[offset + 3]);

    private static string ReadTag(byte[] data, long offset) =>
        new([(char)data[offset], (char)data[offset + 1], (char)data[offset + 2], (char)data[offset + 3]]);
}

