"""Turn a decoded QuickBASIC 4.5 code segment back into BASIC statements.

The compiler emits a call to a separator routine (B$EVCK when the program uses
event trapping, otherwise B$LINA) after every source statement, which gives
exact statement boundaries.  Within a statement the emulated x87 stack and the
argument pushes are interpreted symbolically to rebuild the expression, and the
runtime calls are mapped back through runtime.RUNTIME.
"""

import struct
from .x86 import decode_all
from .runtime import RUNTIME, describe

def is_name(text):
    """True if text can be the target of an assignment or a READ."""
    import re
    return bool(re.match(r'^[A-Za-z][A-Za-z0-9_]*[!%$#&]?(\(.*\))?$', text or ''))


REL = {'je': '=', 'jne': '<>', 'jbe': '<=', 'jb': '<', 'ja': '>', 'jae': '>=',
       'jl': '<', 'jle': '<=', 'jg': '>', 'jge': '>='}
NEG = {'=': '<>', '<>': '=', '<': '>=', '>': '<=', '<=': '>', '>=': '<'}
PUTACT = {0: 'PSET', 1: 'PRESET', 2: 'AND', 3: 'OR', 4: 'XOR'}


class Stmt:
    """One reconstructed statement."""
    __slots__ = ('addr', 'text', 'kind', 'target', 'cond', 'var', 'unsure')

    def __init__(self, addr, text, kind='stmt', target=None, cond=None, var=None,
                 unsure=False):
        self.addr, self.text, self.kind = addr, text, kind
        self.target, self.cond, self.var = target, cond, var
        self.unsure = unsure or '(?)' in text or text.endswith('?')

    def __repr__(self):
        return '<%04X %s %r>' % (self.addr, self.kind, self.text)


class Lifter:
    def __init__(self, module, raw_names=False):
        self.m = module
        self.raw_names = raw_names
        self.code = module.code
        self.cn = module.seg('BC_CN')
        self.fx = module.fixups_in(self.code.name)
        self.cnfx = module.fixups_in('BC_CN')
        self.kind = {}          # BC_DATA offset -> 'f' | 'i' | 's'
        self.names = {}
        self.counters = {'f': 0, 'i': 0, 's': 0, 'a': 0}
        self.arrays = set()
        self.warnings = []
        self.ins = decode_all(bytes(self.code.image), 0, self._entry())
        self.at = {i.addr: n for n, i in enumerate(self.ins)}
        self._classify()

    # ------------------------------------------------------------ helpers
    def _entry(self):
        """Skip BC's module header: code starts at the first relocated call."""
        offs = sorted(self.fx)
        for o in offs:
            if o >= 1 and self.code.image[o - 1] in (0x9A, 0xB8, 0xE8):
                return o - 1
        return 0x30

    def fixup_for(self, ins, op=None):
        if op is not None and op.at is not None:
            return self.fx.get(op.at)
        for o in range(ins.addr, ins.addr + ins.size):
            if o in self.fx:
                return self.fx[o]
        return None

    def cn_pointer(self, off):
        """BC_CN holds relocated far pointers to arrays; resolve one to a name."""
        for o in (off, off - 2):
            f = self.cnfx.get(o)
            if f and f.name == 'BC_DATA':
                return self.var(f.disp, array=True)
        return None

    def const(self, off, size=4):
        c = self.cn
        if not c or off + 4 > c.length:
            return '?'
        img = bytes(c.image)
        if size == 8 and off + 8 <= c.length:
            v = struct.unpack_from('<d', img, off)[0]
            return '%d' % int(v) if v == int(v) and abs(v) < 1e15 else repr(v)
        n = struct.unpack_from('<I', img, off)[0]
        if 0 < n < 256 and off + 4 + n <= c.length:
            txt = img[off + 4:off + 4 + n]
            if all(32 <= ch < 255 for ch in txt):
                return '"%s"' % txt.decode('cp437')
        v = struct.unpack_from('<f', img, off)[0]
        if v == int(v) and abs(v) < 1e9:
            return '%d' % int(v)
        return repr(round(v, 6))

    def _classify(self):
        """Type each BC_DATA slot from the way the code touches it."""
        for i in self.ins:
            f = self.fixup_for(i)
            if not f or f.name != 'BC_DATA':
                continue
            if i.mnem[0] == 'f' and i.mnem != 'fwait':
                sz = i.ops[0].size if i.ops and i.ops[0].kind == 'mem' else 4
                self.kind[f.disp] = 'f' if sz >= 4 else 'i'
            else:
                self.kind.setdefault(f.disp, 'i')
        fp = {o for o, t in self.kind.items() if t == 'f'}
        strish = ('B$SASS', 'B$SCMP', 'B$SCAT', 'B$PESD', 'B$PSSD', 'B$RDSD',
                  'B$FLEN', 'B$FMID')
        for n, i in enumerate(self.ins):
            f = self.fixup_for(i)
            if i.mnem == 'lcall' and f and f.name in strish:
                for j in range(max(0, n - 8), n):
                    ij = self.ins[j]
                    # only an address load ("mov ax, offset v") names a string;
                    # a slot the FPU touches is numeric whatever else happens
                    if ij.mnem != 'mov' or len(ij.ops) != 2 \
                       or ij.ops[1].kind != 'imm':
                        continue
                    g = self.fixup_for(ij, ij.ops[1])
                    if g and g.name == 'BC_DATA' and g.disp not in fp:
                        self.kind[g.disp] = 's'

    def var(self, off, array=False):
        if array:
            self.arrays.add(off)
        if off in self.names:
            return self.names[off]
        t = self.kind.get(off, 'f')
        sfx = {'f': '!', 'i': '%', 's': '$'}[t]
        if self.raw_names:
            nm = 'v%04X%s' % (off, sfx)
        else:
            key = 'a' if array else t
            self.counters[key] += 1
            stem = {'f': 'n', 'i': 'i', 's': 's', 'a': 'arr'}[key]
            nm = '%s%d%s' % (stem, self.counters[key], sfx)
        self.names[off] = nm
        return nm

    TYPE_HINT = {'B$SCAT': 's', 'B$SASS': 's', 'B$SCMP': 's', 'B$PESD': 's',
                 'B$PSSD': 's', 'B$RDSD': 's', 'B$FASC': 's', 'B$FLEN': 's',
                 'B$FMID': 's', 'B$RDI2': 'i', 'B$GPUT': 'i', 'B$GGET': 'i',
                 'B$RDR4': 'f', 'B$PSR4': 'f'}

    def hint_after(self, n):
        """The element type implied by the next runtime call that consumes it."""
        for k in range(n, min(n + 12, len(self.ins))):
            i = self.ins[k]
            if i.mnem != 'lcall':
                continue
            f = self.fixup_for(i)
            if not f:
                continue
            if f.name in self.TYPE_HINT:
                return self.TYPE_HINT[f.name]
            if f.name in ('B$EVCK', 'B$LINA'):
                break
        return None

    def element(self, pending, want):
        """Name an array element now that the consumer has revealed its type."""
        if not pending:
            return None
        base, idx, scale = pending
        t = want or self.kind.get(base) or ('i' if scale == 2 else 'f')
        self.kind.setdefault(base, t)
        if self.kind[base] != t and base not in self.names:
            self.kind[base] = t
        return '%s(%s)' % (self.var(base, array=True), idx)

    def value(self, ins, op):
        """The symbolic value of one operand."""
        f = self.fixup_for(ins, op)
        if f:
            if f.name == 'BC_CN':
                return self.const(f.disp, 8 if op.kind == 'mem' and op.size == 8 else 4)
            if f.name == 'BC_DATA':
                return self.var(f.disp)
            if f.name == self.code.name:
                return 'L%04X' % f.disp
            return f.name
        if op.kind == 'imm':
            return str(op.value)
        if op.kind == 'reg':
            return op.reg
        return str(op)

    # ------------------------------------------------------- FOR recovery
    def _skip_wait(self, k):
        while k < len(self.ins) and self.ins[k].mnem == 'fwait':
            k += 1
        return k

    def find_loops(self):
        """BC compiles FOR by jumping to the increment-and-test at the bottom:

               fld <start> / jmp test
           body:  ...
               fld var / fadd <step>
           test: fstp var / fld <limit> / fld var / call B$FCMP / jbe body
        """
        lines, skip = {}, set()
        I = self.ins
        for k in range(1, len(I) - 6):
            if I[k].mnem != 'jmp' or not I[k].ops or I[k].ops[0].kind != 'rel':
                continue
            if I[k - 1].mnem != 'fld':
                continue
            t = self.at.get(I[k].ops[0].value)
            if t is None or I[t].mnem != 'fstp':
                continue
            v = self.value(I[t], I[t].ops[0])
            j = self._skip_wait(t + 1)
            if j + 3 >= len(I) or I[j].mnem != 'fld':
                continue
            limit = self.value(I[j], I[j].ops[0])
            if I[j + 1].mnem != 'fld' or self.value(I[j + 1], I[j + 1].ops[0]) != v:
                continue
            j3 = self._skip_wait(j + 2)
            g = self.fixup_for(I[j3])
            if I[j3].mnem != 'lcall' or not g or g.name != 'B$FCMP':
                continue
            j4 = j3 + 1
            if not I[j4].mnem.startswith('j') or not I[j4].ops \
               or I[j4].ops[0].kind != 'rel':
                continue
            body = k + 1
            while body < len(I) and I[body].mnem == 'nop':
                body += 1
            if I[j4].ops[0].value != I[body].addr:
                # the test may branch out on exit, falling into a jmp back
                if not (I[j4 + 1].mnem == 'jmp' and I[j4 + 1].ops
                        and I[j4 + 1].ops[0].kind == 'rel'
                        and I[j4 + 1].ops[0].value == I[body].addr):
                    continue
                j4 += 1
            step, inc = '1', t
            if t >= 2 and I[t - 1].mnem in ('fadd', 'fsub') \
               and I[t - 2].mnem == 'fld' \
               and self.value(I[t - 2], I[t - 2].ops[0]) == v:
                step = self.value(I[t - 1], I[t - 1].ops[0])
                if I[t - 1].mnem == 'fsub':
                    step = '-' + step
                inc = t - 2
            lines[k - 1] = Stmt(I[k - 1].addr, 'FOR %s = %s TO %s%s'
                                % (v, self.value(I[k - 1], I[k - 1].ops[0]), limit,
                                   '' if step == '1' else ' STEP %s' % step),
                                'for', var=v)
            lines.setdefault(inc, Stmt(I[inc].addr, 'NEXT %s' % v, 'next', var=v))
            skip.update(range(k - 1, k + 1))
            skip.update(range(inc, j4 + 1))
        return lines, skip

    # -------------------------------------------------------------- lift
    def run(self):
        forlines, forskip = self.find_loops()
        st = []                  # emulated x87 stack, as expression strings
        args = []                # pending pushed arguments
        regs = {}                # ax/bx/... -> expression
        temps = {}               # [bp-N] -> expression
        out = []
        cmp_expr = None          # (lhs, rhs) awaiting a conditional jump
        bool_expr = None         # a materialised -1/0 comparison
        coord = coord2 = None
        array_ptr = None
        pending_read = None
        idx_expr = None
        pend_ax = None
        swallow = 0
        scale = 1
        last_push_off = None

        for n, i in enumerate(self.ins):
            if n in forlines:
                out.append(forlines[n])
            if n in forskip:
                continue
            f = self.fixup_for(i)
            m = i.mnem
            a = i.addr

            # ---- emulated floating point ---------------------------------
            if m == 'fld':
                st.append(self.value(i, i.ops[0]))
            elif m == 'fild':
                st.append('CINT(%s)' % self.value(i, i.ops[0]))
            elif m in ('fadd', 'fsub', 'fmul', 'fdiv', 'fsubr', 'fdivr',
                       'fiadd', 'fisub', 'fimul', 'fidiv'):
                if st:
                    b = self.value(i, i.ops[0])
                    o = {'fadd': '+', 'fiadd': '+', 'fsub': '-', 'fisub': '-',
                         'fmul': '*', 'fimul': '*', 'fdiv': '/', 'fidiv': '/',
                         'fsubr': '-', 'fdivr': '/'}[m]
                    st[-1] = ('(%s %s %s)' % (b, o, st[-1]) if m in ('fsubr', 'fdivr')
                              else '(%s %s %s)' % (st[-1], o, b))
            elif m in ('faddp', 'fmulp', 'fsubp', 'fdivp', 'fsubrp', 'fdivrp'):
                if len(st) >= 2:
                    b, x = st.pop(), st.pop()
                    o = {'faddp': '+', 'fmulp': '*', 'fsubp': '-', 'fdivp': '/',
                         'fsubrp': '-', 'fdivrp': '/'}[m]
                    st.append('(%s %s %s)' % ((x, o, b) if m in
                              ('faddp', 'fmulp', 'fsubp', 'fdivp') else (b, o, x)))
            elif m == 'fchs':
                if st:
                    st[-1] = '-%s' % st[-1]
            elif m == 'fsqrt':
                if st:
                    st[-1] = 'SQR(%s)' % st[-1]
            elif m in ('fstp', 'fst'):
                if st:
                    v = st.pop() if m == 'fstp' else st[-1]
                    dst = i.ops[0]
                    if dst.kind == 'mem' and dst.base is not None:
                        args.append(v)          # pushed onto the stack as an argument
                    else:
                        lhs = self.value(i, dst)
                        out.append(Stmt(a, '%s = %s' % (lhs, v), 'assign',
                                        unsure=not is_name(lhs)))
            elif m in ('fcom', 'fcomp', 'ficom', 'ficomp'):
                if st:
                    cmp_expr = (st[-1], self.value(i, i.ops[0]))
                    if m.endswith('p'):
                        st.pop()

            # ---- argument marshalling ------------------------------------
            elif m == 'push':
                op = i.ops[0]
                if op.kind == 'reg' and op.reg in ('ax', 'dx') and swallow:
                    swallow -= 1
                elif op.kind == 'reg' and op.reg == 'ax' and pend_ax:
                    args.append(pend_ax); pend_ax = None
                elif op.kind == 'imm' and self.fixup_for(i, op) \
                        and self.fixup_for(i, op).name == 'BC_CN' \
                        and self.cn_pointer(self.fixup_for(i, op).disp):
                    array_ptr = self.cn_pointer(self.fixup_for(i, op).disp)
                elif op.kind == 'reg' and op.reg == 'bx' and regs.get('bx'):
                    args.append(regs['bx'])          # far pointer to a variable
                elif op.kind == 'sreg' or (op.kind == 'reg' and op.reg in
                                           ('es', 'bx', 'ds', 'cs', 'si', 'di',
                                            'bp')):
                    pass
                elif op.kind == 'reg' and op.reg == 'ax' \
                        and regs.get('ax') is None and pending_read:
                    # AX holds the address of an array element computed above
                    args.append(self.element(pending_read, self.hint_after(n)))
                    pending_read = None
                elif op.kind == 'reg' and regs.get(op.reg) is not None:
                    args.append(regs[op.reg])
                elif op.kind == 'reg' and op.reg in regs:
                    args.append('?')
                elif op.kind == 'mem':
                    g = self.fixup_for(i, op)
                    if g and g.name == 'BC_CN' and self.cn_pointer(g.disp):
                        array_ptr = self.cn_pointer(g.disp)
                    elif g and g.name in ('BC_DATA', 'BC_CN'):
                        # a 4-byte value is pushed as two words, high half
                        # first: [x+2] then [x].  Merge them back into one.
                        whole = (self.var(g.disp) if g.name == 'BC_DATA'
                                 else self.const(g.disp))
                        if args and last_push_off == (g.name, g.disp + 2):
                            args[-1] = whole
                        else:
                            args.append(self.value(i, op))
                        last_push_off = (g.name, g.disp)
                    else:
                        args.append(self.value(i, op))
                else:
                    args.append(self.value(i, op))

            elif m == 'mov':
                dst, src = i.ops[0], i.ops[1]
                if dst.kind == 'reg':
                    regs[dst.reg] = self.value(i, src) if src.kind != 'reg' \
                        else regs.get(src.reg, src.reg)
                elif dst.kind == 'mem' and dst.base == 'bp' and src.kind == 'reg':
                    temps[dst.disp] = regs.get(src.reg)
                if dst.kind == 'reg' and src.kind == 'mem' and src.base == 'bp':
                    regs[dst.reg] = temps.get(src.disp)
            elif m == 'xor' and len(i.ops) == 2 and i.ops[0].kind == 'reg' \
                    and i.ops[1].kind == 'reg' and i.ops[0].reg == i.ops[1].reg:
                regs[i.ops[0].reg] = '0'
            elif m == 'dec' and i.ops and i.ops[0].kind == 'reg' \
                    and i.ops[0].reg == 'ax' and bool_expr:
                regs['ax'] = bool_expr
                bool_expr = None
            elif m in ('or', 'and') and len(i.ops) == 2 \
                    and i.ops[0].kind == 'reg' and i.ops[1].kind == 'reg':
                x, y = regs.get(i.ops[0].reg), regs.get(i.ops[1].reg)
                if x and y:
                    regs[i.ops[0].reg] = '(%s) %s (%s)' % (x, m.upper(), y)

            # ---- calls ---------------------------------------------------
            elif m == 'lcall' and f:
                nm = f.name
                rt = RUNTIME.get(nm)
                shape = rt.shape if rt else None
                kw = rt.basic if rt else None
                if shape == 'sep':
                    args, regs, temps = [], {}, {}
                    coord = coord2 = pend_ax = array_ptr = None
                    pending_read = idx_expr = None
                    swallow = 0
                    scale = 1
                    cmp_expr = bool_expr = None
                    last_push_off = None
                    del st[:]
                    last_push_off = None
                elif shape == 'ignore':
                    args = []
                elif shape == 'compare':
                    if len(st) >= 2:
                        b, x = st.pop(), st.pop()
                        cmp_expr = (b, x)
                elif shape == 'scompare':
                    if len(args) >= 2:
                        cmp_expr = (args[-2], args[-1])
                        args = args[:-2]
                elif shape == 'cvt_ax':
                    idx_expr = st.pop() if st else '?'
                    pend_ax = 'CINT(%s)' % idx_expr
                    regs['ax'] = pend_ax
                elif shape == 'cvt_dxax':
                    args.append('CLNG(%s)' % (st.pop() if st else '?'))
                    swallow = 2
                elif shape == 'coord1':
                    coord = ('(%s)' % ', '.join(args[-2:])) if len(args) >= 2 \
                        else None
                    args = args[:-2]
                elif shape == 'coord2':
                    coord2 = ('(%s)' % ', '.join(args[-2:])) if len(args) >= 2 \
                        else None
                    args = args[:-2]
                elif shape == 'opt':
                    out.append(Stmt(a, ('%s %s' % (kw, decode_opt(args))).strip()))
                    args = []
                elif shape == 'args':
                    out.append(Stmt(a, '%s %s' % (kw, ', '.join(args))))
                    args = []
                elif shape in ('print', 'print_nl'):
                    v = self.element(pending_read, 's') if pending_read \
                        else (args[-1] if args else '')
                    pending_read = None
                    out.append(Stmt(a, 'PRINT %s%s' % (v, ';' if shape == 'print'
                                                       else '')))
                    args = []
                elif shape in ('print_fp', 'print_fp_nl'):
                    v = st.pop() if st else (args[-1] if args else '')
                    out.append(Stmt(a, 'PRINT %s%s' % (v, ';' if shape == 'print_fp'
                                                       else '')))
                    args = []
                elif shape == 'print_end':
                    out.append(Stmt(a, 'PRINT'))
                    args = []
                elif shape == 'line':
                    box = {'1': ', B', '2': ', BF'}.get(args[-1] if args else '', '')
                    col = args[0] if args else ''
                    style = args[1] if len(args) > 1 else ''
                    if style in ('65535', '-1'):
                        style = ''
                    out.append(Stmt(a, 'LINE %s-%s, %s%s'
                                    % (coord or '(?)', coord2 or '(?)', col, box),
                                    unsure=not (coord and coord2)))
                    args = []; coord = coord2 = None
                elif shape == 'circle':
                    out.append(Stmt(a, 'CIRCLE %s, %s' % (coord or '(?)',
                                                          ', '.join(args))))
                    args = []; coord = None
                elif shape == 'graph':
                    out.append(Stmt(a, '%s %s%s' % (kw, coord or '(?)',
                                    (', ' + ', '.join(args)) if args else '')))
                    args = []; coord = None
                elif shape == 'put':
                    act = PUTACT.get(int(args[-1]) if args and args[-1].isdigit()
                                     else -1, args[-1] if args else '')
                    el = self.element(pending_read, 'i') or array_ptr
                    out.append(Stmt(a, 'PUT %s, %s, %s'
                                    % (coord or '(?)', el or '?', act),
                                    unsure=not (coord and el)))
                    array_ptr = None
                    pending_read = None
                    args = []; coord = None
                elif shape == 'get':
                    el = self.element(pending_read, 'i') or array_ptr
                    out.append(Stmt(a, 'GET %s-%s, %s'
                                    % (coord or '(?)', coord2 or '(?)', el or '?'),
                                    unsure=not (coord and coord2 and el)))
                    pending_read = None
                    args = []; coord = None
                elif shape == 'draw':
                    out.append(Stmt(a, '%s %s' % (kw, args[-1] if args else '?')))
                    args = []
                elif shape == 'gosub':
                    t = None
                    for j in range(max(0, n - 3), n):
                        g = self.fixup_for(self.ins[j])
                        if g and g.name == self.code.name:
                            t = g.disp
                    out.append(Stmt(a, 'GOSUB L%04X' % (t or 0), 'gosub', t))
                elif shape == 'read':
                    want = {'B$RDI2': 'i', 'B$RDR4': 'f', 'B$RDSD': 's'}[nm]
                    # the target is the first argument: B$RDSD follows it with
                    # a flag word, so the last argument is the wrong one
                    tgt = self.element(pending_read, want) or (args[0] if args
                                                               else '?')
                    out.append(Stmt(a, 'READ %s' % tgt, unsure=not is_name(tgt)))
                    pending_read = None; args = []
                elif shape == 'restore':
                    t = None
                    for j in range(max(0, n - 3), n):
                        g = self.fixup_for(self.ins[j])
                        if g and g.name == self.code.name:
                            t = g.disp
                    out.append(Stmt(a, 'RESTORE L%04X' % (t or 0), 'stmt', t))
                    args = []
                elif shape == 'sassign':
                    if pending_read and len(args) >= 1:
                        lhs = self.element(pending_read, 's')
                        out.append(Stmt(a, '%s = %s'
                                        % (lhs,
                                           args[-2] if len(args) > 1 else args[-1]),
                                        'assign', unsure=not is_name(lhs)))
                        pending_read = None; args = []
                    elif len(args) >= 2:
                        out.append(Stmt(a, '%s = %s' % (args[-1], args[-2]),
                                        'assign', unsure=not is_name(args[-1])))
                        args = args[:-2]
                elif shape == 'sconcat':
                    if len(args) >= 2:
                        pend_ax = '%s + %s' % (args[-2], args[-1])
                        args = args[:-2]
                        regs['ax'] = pend_ax
                elif shape == 'fileio':
                    # (file number, ES:BX = variable, record number)
                    fn = args[0] if args else '?'
                    v = args[1] if len(args) > 1 else None
                    rec = args[2] if len(args) > 2 else '0'
                    out.append(Stmt(a, '%s #%s, %s, %s'
                                    % (kw, fn, '' if rec in ('0', '?') else rec,
                                       v or '?'), unsure=v is None))
                    args = []
                elif shape == 'fn0':
                    pend_ax = kw
                    regs['ax'] = kw
                elif shape == 'fn_int':
                    pend_ax = '%s(%s)' % (kw, args.pop() if args else '?')
                    regs['ax'] = pend_ax
                elif shape == 'fn_st':
                    st.append('%s(%s)' % (kw, st.pop() if st else '?'))
                elif shape == 'fn_fp':
                    v = st.pop() if st else (args.pop() if args else '?')
                    pend_ax = '%s(%s)' % (kw, v)
                    regs['ax'] = pend_ax
                elif shape == 'open':
                    # (filename, file number, record length or -1, flag word).
                    # The flag encoding is not fully decoded; a record length
                    # of -1 with byte-sized GETs means the file was opened FOR
                    # BINARY, so that is what is emitted, with the raw values
                    # kept in a comment.
                    fn = args[0] if args else '?'
                    num = args[1] if len(args) > 1 else '?'
                    reclen = args[2] if len(args) > 2 else ''
                    flags = args[3] if len(args) > 3 else ''
                    ln = ''
                    if reclen not in ('', '65535', '-1'):
                        ln = ' LEN = %s' % reclen
                    out.append(Stmt(
                        a, 'OPEN %s FOR BINARY AS #%s%s'
                           '   \' open flags %s%s; mode inferred from the '
                           'byte-sized GETs' % (fn, num, ln, flags,
                            ', no LEN' if not ln else '')))
                    args = []
                elif shape == 'close':
                    out.append(Stmt(a, 'CLOSE #%s' % (args[0] if args else '')))
                    args = []
                elif shape == 'none':
                    out.append(Stmt(a, kw))
                    args = []
                elif shape in ('trap_on', 'trap_off'):
                    out.append(Stmt(a, "' event trapping %s"
                                    % ('ON' if shape == 'trap_on' else 'OFF'),
                                    'comment'))
                elif shape == 'ontable':
                    out.append(Stmt(a, "' ON <event> GOSUB (jump table)", 'comment'))
                    args = []
                else:
                    d = describe(nm)
                    out.append(Stmt(a, "' %s(%s)%s" % (nm, ', '.join(args),
                                    '   [' + d + ']' if d else ''), 'comment'))
                    args = []

            # ---- array element address: base + scaled index ---------------
            elif m == 'shl' and i.ops and i.ops[0].kind == 'reg' \
                    and i.ops[0].reg == 'ax':
                scale *= 2
            elif m == 'add' and i.ops and i.ops[0].kind == 'reg' \
                    and i.ops[0].reg == 'ax' and f and f.name == 'BC_DATA':
                pending_read = (f.disp, idx_expr or '?', scale)
                regs['ax'] = None
                pend_ax = None
                scale = 1

            # ---- comparisons and branches ---------------------------------
            elif m == 'cmp':
                def rv(op):
                    if op.kind == 'reg' and regs.get(op.reg):
                        return regs[op.reg]
                    return self.value(i, op)
                cmp_expr = (rv(i.ops[0]), rv(i.ops[1]))
            elif m.startswith('j') and i.ops and i.ops[0].kind == 'rel':
                t = i.ops[0].value
                if m == 'jmp':
                    out.append(Stmt(a, 'GOTO L%04X' % t, 'goto', t))
                elif cmp_expr and self.ins[n + 1].addr == t and m in REL:
                    # "jump over the next instruction" - materialise a boolean
                    bool_expr = '%s %s %s' % (cmp_expr[0], NEG[REL[m]], cmp_expr[1])
                elif cmp_expr and m in REL:
                    c = ('rel', cmp_expr[0], REL[m], cmp_expr[1])
                    out.append(Stmt(a, 'IF %s THEN GOTO L%04X' % (cond_text(c), t),
                                    'if', t, c))
                    cmp_expr = None
                elif regs.get('ax') and m in ('je', 'jne'):
                    c = ('bool', regs['ax']) if m == 'jne' else \
                        ('not', regs['ax'])
                    out.append(Stmt(a, 'IF %s THEN GOTO L%04X' % (cond_text(c), t),
                                    'if', t, c))
                else:
                    c = ('raw', m)
                    out.append(Stmt(a, 'IF %s THEN GOTO L%04X' % (cond_text(c), t),
                                    'if', t, c))

        for addr, text in self.m.datastmts.items():
            out.append(Stmt(addr, 'DATA %s' % text, 'data'))
        out.sort(key=lambda s: s.addr)
        return out


def cond_text(c):
    if c[0] == 'rel':
        return '%s %s %s' % (c[1], c[2], c[3])
    if c[0] == 'bool':
        return c[1]
    if c[0] == 'not':
        return 'NOT (%s)' % c[1]
    return '<%s>' % c[1]


def cond_negate(c):
    if c[0] == 'rel':
        return ('rel', c[1], NEG[c[2]], c[3])
    if c[0] == 'bool':
        return ('not', c[1])
    if c[0] == 'not':
        return ('bool', c[1])
    return ('raw', 'not ' + c[1])


def decode_opt(args):
    """(present-flag, value) pairs followed by a mask word."""
    vals, k = [], 0
    while k + 1 < len(args):
        vals.append(args[k + 1] if args[k] != '0' else '')
        k += 2
    while vals and vals[-1] == '':
        vals.pop()
    return ', '.join(vals)

